Create a readable service diagram for the supplied checkout system, separating synchronous purchase requests from the asynchronous fulfillment event and showing the stated trust boundary.

Public task packet:
{
  "id": "dev-architecture-create-checkout",
  "title": "Checkout request path",
  "domain": "architecture",
  "stratum": "creation",
  "operation": "create",
  "complexity": "medium",
  "brief": "Create a readable service diagram for the supplied checkout system, separating synchronous purchase requests from the asynchronous fulfillment event and showing the stated trust boundary.",
  "stressors": [
    "negative_constraints"
  ],
  "antiGamingCases": [
    "duplicate_keyword"
  ],
  "publicEvaluationDimensions": [
    "semantic_correctness",
    "geometry_readability",
    "perceptual_quality",
    "self_correction",
    "presentation_ux",
    "efficiency",
    "document_integrity"
  ],
  "acceptanceCriteria": [
    {
      "id": "criterion-checkout-facts",
      "text": "Show every supplied entity and directed relationship exactly once, with synchronous requests visually distinct from the asynchronous event."
    },
    {
      "id": "criterion-checkout-boundary",
      "text": "Place Shopper Browser outside and Checkout API, Payment Service, and Fulfillment Worker inside the commerce trust boundary."
    },
    {
      "id": "criterion-checkout-readable",
      "text": "Keep every essential node and label visible and readable, with no connector intrusion or duplicate semantic object used for credit."
    }
  ],
  "requiredCapabilities": [
    "capability_discovery",
    "authoritative_state_read",
    "staged_authoring",
    "semantic_mutation",
    "visual_inspection",
    "targeted_correction"
  ],
  "initialState": {
    "kind": "blank"
  },
  "publicTaskPacket": {
    "kind": "architecture",
    "materials": [
      {
        "id": "source-checkout-system",
        "title": "Checkout system facts",
        "sourceKind": "task_authoritative_synthetic",
        "content": "Shopper Browser sends a checkout request to Checkout API. Checkout API requests authorization from Payment Service, then publishes an order-created event to Fulfillment Worker. The browser is outside the commerce trust boundary; all three services are inside."
      }
    ],
    "entities": [
      {
        "id": "shopper-browser",
        "label": "Shopper Browser",
        "description": "Customer browser outside the commerce trust boundary."
      },
      {
        "id": "checkout-api",
        "label": "Checkout API",
        "description": "Receives checkout requests and coordinates purchase work."
      },
      {
        "id": "payment-service",
        "label": "Payment Service",
        "description": "Authorizes payment for Checkout API."
      },
      {
        "id": "fulfillment-worker",
        "label": "Fulfillment Worker",
        "description": "Consumes the order-created event."
      }
    ],
    "relationships": [
      {
        "id": "browser-checkout",
        "fromEntityId": "shopper-browser",
        "toEntityId": "checkout-api",
        "relationshipType": "synchronous_request",
        "description": "Browser sends checkout request to Checkout API."
      },
      {
        "id": "checkout-payment",
        "fromEntityId": "checkout-api",
        "toEntityId": "payment-service",
        "relationshipType": "synchronous_request",
        "description": "Checkout API requests payment authorization."
      },
      {
        "id": "checkout-fulfillment",
        "fromEntityId": "checkout-api",
        "toEntityId": "fulfillment-worker",
        "relationshipType": "asynchronous_event",
        "description": "Checkout API publishes order-created to Fulfillment Worker."
      }
    ],
    "uncertaintyConstraints": [
      {
        "id": "checkout-no-invention",
        "text": "Do not add databases, queues, protocols, vendors, or security controls not stated in this packet."
      }
    ]
  }
}

